var t=`0439-krumkake`;var i=`world-0439`;var r=`NO`;var a=`northern-europe`;var o=8;var s=27;var u={en:`Krumkake`,ua:`Крумкаке`};var g={en:`A traditional dish from Norway, centered on chicken egg, all-purpose flour. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Норвегія. Основні складники: куряче яйце, пшеничне борошно універсальне. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:7,i:[[`unsalted-butter`,100,`g`],[`white-granulated-sugar`,110,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Gently fold in the remaining dry or wet ingredients just until homogeneous, without deflating the mixture.`,ua:`Обережно вмішайте решту сухих або рідких складників лише до однорідності, не осаджуючи масу.`,t:[`folding-batter`],m:4,i:[[`all-purpose-flour`,130,`g`],[`ground-cardamom`,3,`g`],[`vanilla-extract`,3,`ml`]]},{en:`Cook the batter as very thin round wafers in a krumkake iron, then immediately roll each hot wafer around a cone form.`,ua:`Випікайте дуже тонкі круглі вафлі в спеціальній вафельниці для крумкаке, одразу згорніть гарячі вафлі навколо конічної форми.`,t:[`pan-frying`],m:13,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,25,`g`]]}];var l={slug:t,id:i,country:`NO`,region:a,servings:8,minutes:27,title:u,text:g,steps:d};export{r as country,l as default,i as id,s as minutes,a as region,o as servings,t as slug,d as steps,g as text,u as title};